(* [comment removed for export] *)
Definition ecat_vt_cells : list cell :=
  [C8 (Z_to_bv 64 0x34598); C8 (Z_to_bv 64 0x345a4); C8 (Z_to_bv 64 0x345bc); C8 (Z_to_bv 64 0x345f4);
   C8 (Z_to_bv 64 0x346a4); C8 (Z_to_bv 64 0x346f4); C8 (Z_to_bv 64 0x2cb68)].

Lemma XStatics_ecat_vt : forall m, XStatics m -> rw_cells usegs m 0x7f068 ecat_vt_cells.
Proof. intros m XS. unfold XStatics in XS. destruct XS as (_ & _ & _ & _ & _ & _ & _ & H & _). exact H. Qed.

Lemma XStatics_after_assign : forall m m' lo hi D,
  XStatics m -> munch [(lo, hi); (D, D + 24); (610384, 610384 + 64)]%Z m m' -> wmono usegs m m' ->
  0xb8000 <= lo -> lo <= D -> XStatics m'.
Proof.
  intros m m' lo hi D XS MU WM H1 H2. eapply XStatics_transport; [exact XS | exact MU | exact WM |].
  repeat constructor; cbn; lia.
Qed.
Scheme kc__3 := Elimination for Corelib.Init.Datatypes.bool Sort Prop.

Lemma HttpCat_to_internal : forall m g, HttpCat m g ->
  rw_cells usegs m 610384 (hc_cells g (zeros 52) (zeros 4)) /\ rw_cells usegs m 610440 (hg_cells (if g then 1 else 0) (if g then 1 else 0) (zeros 6)).
Proof.
  intros m g [OB GD]. split.
  - eapply rw_cells_reshape; [exact OB | destruct g; vm_compute; repeat split | destruct g; vm_compute; reflexivity].
  - eapply rw_cells_reshape; [exact GD | destruct g; vm_compute; repeat split | destruct g; vm_compute; reflexivity].
Qed.

Lemma HttpCat_of_internal : forall m,
  rw_cells usegs m 610384 (hc_cells true [] (zeros 4)) -> rw_cells usegs m 610440 (hg_cells 1 1 (zeros 6)) ->
  HttpCat m true.
Proof.
  intros m OB GD. unfold HttpCat, G_HTTP_CAT, G_HTTP_CAT_GUARD. cbn [HttpCatCells HttpCatGuardCells]. split.
  - eapply rw_cells_reshape; [exact OB | cbn; repeat split; reflexivity | vm_compute; reflexivity].
  - eapply rw_cells_reshape; [exact GD | cbn; repeat split; reflexivity | vm_compute; reflexivity].
Qed.

